// Builds a short alert text from an n8n Error Trigger payload.
// Deliberately leaves out node input/output data, stack traces and credentials.
const err = $input.first().json;
const exec = err.execution || {};
const execError = exec.error || {};
const workflow = (err.workflow && err.workflow.name) || 'unknown workflow';
const node = (execError.node && execError.node.name) || 'unknown node';
const message = String(execError.message || 'no message').slice(0, 300);
const text = '[ALERT] ' + workflow + ' failed at "' + node + '": ' + message + '. Execution: ' + (exec.id || 'unknown');
return [{ json: { text } }];
